        { you: { cue: 'Say you studied maths at university, in Toulouse.', t: 'Moi, j’ai fait des maths à la fac, à Toulouse.', en: 'I studied maths at university, in Toulouse.',
          alt: ['Moi, j’ai fait des maths à la fac de Toulouse.', 'J’ai étudié les maths à l’université, à Toulouse.'],
          gloss: 'moi = me (put first for contrast) · j’ai fait = I did (faire) · des maths = maths · à la fac = at uni (short for faculté) · à Toulouse = in Toulouse' } }
